ALTER TABLE public.qw_lideres DROP CONSTRAINT qw_lideres_cargo_check;
ALTER TABLE public.qw_lideres ADD CONSTRAINT qw_lideres_cargo_check CHECK (cargo IN ('diretor','gerente','coordenador','supervisor','outro'));
ALTER TABLE public.qw_lideres ADD COLUMN diretor_lider_id uuid REFERENCES public.qw_lideres(id), ADD COLUMN triagem_governanca boolean NOT NULL DEFAULT false;
ALTER TABLE public.qw_itens ADD COLUMN area_rotulo text;
ALTER TABLE public.qw_envios ADD COLUMN aguardando_diretor boolean NOT NULL DEFAULT false;
CREATE TABLE public.qw_lider_diretores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lider_id uuid NOT NULL REFERENCES public.qw_lideres(id), diretor_lider_id uuid REFERENCES public.qw_lideres(id), diretor_user_id uuid, area_rotulo text NOT NULL CHECK (btrim(area_rotulo)<>''), ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.qw_lider_diretores TO authenticated;
GRANT ALL ON public.qw_lider_diretores TO service_role;
ALTER TABLE public.qw_lider_diretores ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX qw_diretores_area_ativa ON public.qw_lider_diretores(lider_id, lower(btrim(area_rotulo))) WHERE ativo;
CREATE FUNCTION public.qw_email_chave(_email text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT replace(split_part(lower(btrim(_email)),'@',1),'.','') || '@' || split_part(lower(btrim(_email)),'@',2); $$;
CREATE UNIQUE INDEX qw_lideres_email_chave ON public.qw_lideres(public.qw_email_chave(email));
CREATE OR REPLACE FUNCTION public.is_lider_restrito(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _uid IS NOT NULL AND EXISTS(SELECT 1 FROM public.qw_lideres WHERE user_id=_uid AND ativo AND cargo<>'diretor') AND NOT EXISTS(SELECT 1 FROM public.qw_lideres WHERE user_id=_uid AND ativo AND cargo='diretor') AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_uid) AND NOT EXISTS(SELECT 1 FROM public.mt_usuarios WHERE user_id=_uid); $$;
CREATE FUNCTION public.qw_resolver_diretor(_user uuid, _lider uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(_user,(SELECT user_id FROM public.qw_lideres WHERE id=_lider AND ativo AND cargo='diretor')); $$;
CREATE FUNCTION public.qw_diretor_item(_lider uuid, _area text) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM public.qw_lider_diretores WHERE lider_id=l.id AND ativo) THEN (SELECT public.qw_resolver_diretor(d.diretor_user_id,d.diretor_lider_id) FROM public.qw_lider_diretores d WHERE d.lider_id=l.id AND d.ativo AND (d.area_rotulo=_area OR (_area IS NULL AND (SELECT count(*) FROM public.qw_lider_diretores WHERE lider_id=l.id AND ativo)=1)) LIMIT 1) ELSE public.qw_resolver_diretor(l.diretor_user_id,l.diretor_lider_id) END FROM public.qw_lideres l WHERE l.id=_lider AND l.ativo; $$;
CREATE FUNCTION public.qw_diretor_do_lider(_lider uuid, _uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(_uid IS NOT NULL AND EXISTS(SELECT 1 FROM public.qw_lideres l WHERE l.id=_lider AND l.ativo AND CASE WHEN EXISTS(SELECT 1 FROM public.qw_lider_diretores WHERE lider_id=l.id AND ativo) THEN EXISTS(SELECT 1 FROM public.qw_lider_diretores d WHERE d.lider_id=l.id AND d.ativo AND public.qw_resolver_diretor(d.diretor_user_id,d.diretor_lider_id)=_uid) ELSE public.qw_resolver_diretor(l.diretor_user_id,l.diretor_lider_id)=_uid END),false); $$;
CREATE OR REPLACE FUNCTION public.qw_pode_ler_lider(_lider uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.qw_gov(auth.uid()) OR EXISTS(SELECT 1 FROM public.qw_lideres WHERE id=_lider AND user_id=auth.uid()) OR public.qw_diretor_do_lider(_lider,auth.uid()); $$;
CREATE FUNCTION public.qw_pode_triar_item(_item uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(public.qw_gov(auth.uid()) OR EXISTS(SELECT 1 FROM public.qw_itens i JOIN public.qw_envios e ON e.id=i.envio_id WHERE i.id=_item AND public.qw_diretor_item(e.lider_id,i.area_rotulo)=auth.uid()),false); $$;
CREATE FUNCTION public.qw_pode_ler_item(_item uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.qw_gov(auth.uid()) OR public.qw_pode_triar_item(_item) OR EXISTS(SELECT 1 FROM public.qw_itens i JOIN public.qw_envios e ON e.id=i.envio_id JOIN public.qw_lideres l ON l.id=e.lider_id WHERE i.id=_item AND l.user_id=auth.uid()); $$;
ALTER POLICY qw_lideres_ler ON public.qw_lideres USING(public.qw_pode_ler_lider(id));
ALTER POLICY qw_itens_ler ON public.qw_itens USING(public.qw_pode_ler_item(id));
ALTER POLICY qw_ciclos_ler ON public.qw_ciclos USING(public.qw_gov(auth.uid()) OR (status<>'rascunho' AND EXISTS(SELECT 1 FROM public.qw_lideres l WHERE l.ativo AND (l.user_id=auth.uid() OR public.qw_diretor_do_lider(l.id,auth.uid())))));
CREATE POLICY qw_lider_diretores_ler ON public.qw_lider_diretores FOR SELECT TO authenticated USING(public.qw_gov(auth.uid()) OR EXISTS(SELECT 1 FROM public.qw_lideres WHERE id=lider_id AND user_id=auth.uid()) OR (ativo AND public.qw_resolver_diretor(diretor_user_id,diretor_lider_id)=auth.uid()));
CREATE FUNCTION public.qw_envio_aguarda(_envio uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.qw_itens i JOIN public.qw_envios e ON e.id=i.envio_id JOIN public.qw_lideres l ON l.id=e.lider_id WHERE e.id=_envio AND e.status='enviado' AND i.status_execucao<>'cancelado' AND i.status_triagem='pendente' AND NOT l.triagem_governanca AND public.qw_diretor_item(l.id,i.area_rotulo) IS NULL); $$;
CREATE FUNCTION public.qw_atualizar_encaminhamentos() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _e record; BEGIN
 FOR _e IN SELECT id,aguardando_diretor FROM public.qw_envios WHERE status='enviado' LOOP
 UPDATE public.qw_envios SET aguardando_diretor=public.qw_envio_aguarda(id) WHERE id=_e.id;
 IF _e.aguardando_diretor IS DISTINCT FROM public.qw_envio_aguarda(_e.id) THEN PERFORM public.qw_audit('qw_envios',_e.id,'aguardando_diretor',_e.aguardando_diretor::text,public.qw_envio_aguarda(_e.id)::text); END IF;
 END LOOP;
 UPDATE public.qw_avisos a SET status='cancelado' WHERE a.tipo='envio_diretor' AND a.status='aguardando_remetente' AND a.item_id IS NOT NULL AND a.destinatario_user_id IS DISTINCT FROM (SELECT public.qw_diretor_item(e.lider_id,i.area_rotulo) FROM public.qw_itens i JOIN public.qw_envios e ON e.id=i.envio_id WHERE i.id=a.item_id);
 INSERT INTO public.qw_avisos(tipo,destinatario_user_id,envio_id,item_id) SELECT 'envio_diretor',public.qw_diretor_item(e.lider_id,i.area_rotulo),e.id,i.id FROM public.qw_itens i JOIN public.qw_envios e ON e.id=i.envio_id WHERE e.status='enviado' AND i.status_triagem='pendente' AND i.status_execucao<>'cancelado' AND public.qw_diretor_item(e.lider_id,i.area_rotulo) IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.qw_avisos a WHERE a.item_id=i.id AND a.tipo='envio_diretor' AND a.destinatario_user_id=public.qw_diretor_item(e.lider_id,i.area_rotulo) AND a.status IN ('aguardando_remetente','enviado'));
 END $$;
CREATE FUNCTION public.qw_encaminhamento_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.qw_atualizar_encaminhamentos(); RETURN NEW; END $$;
CREATE TRIGGER qw_lider_encaminhamento AFTER INSERT OR UPDATE ON public.qw_lideres FOR EACH STATEMENT EXECUTE FUNCTION public.qw_encaminhamento_guard();
CREATE TRIGGER qw_vinculos_encaminhamento AFTER INSERT OR UPDATE ON public.qw_lider_diretores FOR EACH STATEMENT EXECUTE FUNCTION public.qw_encaminhamento_guard();
CREATE FUNCTION public.qw_area_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _l uuid; _n int; BEGIN SELECT lider_id INTO _l FROM public.qw_envios WHERE id=NEW.envio_id; SELECT count(*) INTO _n FROM public.qw_lider_diretores WHERE lider_id=_l AND ativo; NEW.area_rotulo:=nullif(btrim(NEW.area_rotulo),''); IF NEW.area_rotulo IS NOT NULL AND _n>0 AND NOT EXISTS(SELECT 1 FROM public.qw_lider_diretores WHERE lider_id=_l AND ativo AND area_rotulo=NEW.area_rotulo) THEN RAISE EXCEPTION 'Área inválida'; END IF; IF _n>1 AND NEW.area_rotulo IS NULL AND EXISTS(SELECT 1 FROM public.qw_envios WHERE id=NEW.envio_id AND status='enviado') THEN RAISE EXCEPTION 'Área obrigatória'; END IF; RETURN NEW; END $$;
CREATE TRIGGER qw_area_guard BEFORE INSERT OR UPDATE ON public.qw_itens FOR EACH ROW EXECUTE FUNCTION public.qw_area_guard();
REVOKE EXECUTE ON FUNCTION public.qw_atualizar_encaminhamentos(),public.qw_audit(text,uuid,text,text,text) FROM PUBLIC,anon,authenticated;